def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n < 5:
        return 'C'
    last_me, last_opp = history[-1]
    if n == 100:
        return 'D'
    if n > 90:
        return 'D'
    def opp_defections(last_k):
        k = min(last_k, n)
        c = 0
        for i in range(n - k, n):
            if history[i][1] == 'D':
                c += 1
        return c
    def my_defections(last_k):
        k = min(last_k, n)
        c = 0
        for i in range(n - k, n):
            if history[i][0] == 'D':
                c += 1
        return c
    recent_opp_def = opp_defections(10)
    recent_my_def = my_defections(10)
    if recent_opp_def >= 7:
        return 'D'
    if recent_opp_def <= 1 and recent_my_def <= 3:
        return 'C'
    total_opp_def = 0
    for h in history:
        if h[1] == 'D':
            total_opp_def += 1
    if total_opp_def >= 40:
        return 'D'
    if last_opp == 'D' and last_me == 'C':
        return 'D'
    if last_opp == 'D' and last_me == 'D':
        r = rng.random()
        if r < 0.7:
            return 'D'
        return 'C'
    if last_opp == 'C':
        if recent_opp_def >= 3:
            return 'D'
        return 'C'
    return 'C'
